expression.expression:
coalesce(                                                                                                                                                                                                           
   TRY_CAST (                                                                                                                                                                                                         
     REGEXP_EXTRACT(                                                                                                                                                                                                 
       REGEXP_REPLACE(double_value, '[ ,\\x27]', ''),   -- strip space, comma, apostrophe                                                                                                                                     
       '^[0-9]*\\.?[0-9]+',                     -- leading number, one optional '.'                                                                                                                                  
       0                                                                                                                                                                                                             
     ) AS DOUBLE                                -- always DOUBLE                                                                                                                                                     
   ),                                                                                                                                                                                                                
   0                                            -- non-numeric → 0                                                                                                                                                   
 )
